// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("build_and_review_basket",
			mcplib.WithDescription("Search catalog for products, add items to cart, and review basket totals before the edit window closes"),
			mcplib.WithString("query", mcplib.Required(), mcplib.Description("Product search term (e.g. 'arroz', 'detergente')")),
			mcplib.WithString("store", mcplib.Description("Store to shop in: programada, fresh, pet, unica, now, now-bebidas")),
		),
		handleBuildAndReviewBasket,
	)
	s.AddTool(
		mcplib.NewTool("check_upcoming_charges",
			mcplib.WithDescription("Get charge date, edit-lock deadline, and delivery date for a store's next cycle"),
			mcplib.WithString("store", mcplib.Description("Store to check: programada, fresh, pet (subscription stores only)")),
		),
		handleCheckUpcomingCharges,
	)
	s.AddTool(
		mcplib.NewTool("order_history_and_spend",
			mcplib.WithDescription("List past orders and compute month-over-month spend across all storefronts"),
			mcplib.WithNumber("months", mcplib.Description("Number of months to look back (default 6)")),
		),
		handleOrderHistoryAndSpend,
	)
}

